CREATE TABLE `pulse_cascade_recipients` (`id` varchar(36) NOT NULL,`cascadingMessageId` varchar(36) NOT NULL,`personId` int NOT NULL,`viaMeetingId` varchar(36) NOT NULL,`acknowledgedAt` timestamp NULL,`acknowledgedFrom` varchar(64) NULL,`createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY (`id`),UNIQUE KEY `pulse_cascade_recipient_unique` (`cascadingMessageId`,`personId`,`viaMeetingId`),KEY `pulse_cascade_recipient_person_idx` (`personId`,`acknowledgedAt`));
CREATE TABLE `pulse_notifications` (`id` varchar(36) NOT NULL,`personId` int NOT NULL,`notificationType` enum('mention','comment','assignment','cascade','proposed_issue','reminder','overdue') NOT NULL,`requiresAction` tinyint NOT NULL DEFAULT 0,`sourceType` varchar(64) NOT NULL,`sourceId` varchar(36) NOT NULL,`meetingId` varchar(36) NULL,`body` text NOT NULL,`clearedAt` timestamp NULL,`createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY (`id`),KEY `pulse_notifications_person_action_idx` (`personId`,`requiresAction`,`clearedAt`,`createdAt`));
CREATE TABLE `pulse_cascade_destinations` (`id` varchar(36) NOT NULL,`cascadingMessageId` varchar(36) NOT NULL,`meetingId` varchar(36) NOT NULL,`createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY (`id`),UNIQUE KEY `pulse_cascade_destination_unique` (`cascadingMessageId`,`meetingId`));
CREATE TABLE `pulse_notification_preferences` (`id` varchar(36) NOT NULL,`personId` int NOT NULL,`templateKey` varchar(64) NOT NULL,`inApp` tinyint NOT NULL DEFAULT 1,`email` tinyint NOT NULL DEFAULT 1,`createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,`updatedAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY (`id`),UNIQUE KEY `pulse_notification_preference_person_template_unique` (`personId`,`templateKey`),KEY `pulse_notification_preference_person_idx` (`personId`));
